import time

# Leaky: every caller knows the cache stores (value, expires_at) tuples
# cache["user:42"] = (user, time.time() + 300)
# value, expires_at = cache["user:42"]

class TTLCache:
    """Key-value cache where entries vanish ttl_seconds after being set."""

    def __init__(self, ttl_seconds, clock=time.monotonic):
        self._ttl, self._clock, self._data = ttl_seconds, clock, {}

    def set(self, key, value):
        self._data[key] = (value, self._clock() + self._ttl)

    def get(self, key, default=None):
        item = self._data.get(key)
        if item is None or self._clock() >= item[1]:
            self._data.pop(key, None)
            return default
        return item[0]

