package main

import (
    "fmt"
    "sync"
)

func main() {
    jobs := make(chan int)
    results := make(chan int)
    var wg sync.WaitGroup

    for w := 0; w < 3; w++ { // 3 workers
        wg.Add(1)
        go func() {
            defer wg.Done()
            for n := range jobs { // loop ends when jobs is closed
                results <- n * n
            }
        }()
    }

    go func() { // producer
        for i := 1; i <= 5; i++ {
            jobs <- i
        }
        close(jobs)
    }()

    go func() { wg.Wait(); close(results) }() // close results once all workers are done

    sum := 0
    for r := range results {
        sum += r
    }
    fmt.Println(sum) // 55, whichever worker squared which number
}

